import{_ as a,a0 as s,w as l,s as d,ao as i,I as r,x as t,a1 as p,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"安装完最小化 RHEL/CentOS 7 后需要做的 30 件事情（四） | LCTT x X-CMD","titleTemplate":false,"description":"安装完最小化 RHEL/CentOS 7 后需要做的 30 件事情（四） | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安装完最小化 RHEL/CentOS 7 后需要做的 30 件事情（四） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安装完最小化 RHEL/CentOS 7 后需要做的 30 件事情（四） | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/30 Things to Do After Minimal RHEL or CentOS 7 Installation--4","title":"安装完最小化 RHEL/CentOS 7 后需要做的 30 件事情（四）","tag":"201505","desc":""},"relativePath":"201505/30 Things to Do After Minimal RHEL or CentOS 7 Installation--4.md","filePath":"[post].md"}'),m={name:"201505/30 Things to Do After Minimal RHEL or CentOS 7 Installation--4.md"};function c(u,e,h,w,f,L){const n=s("Link");return l(),d("div",null,[e[16]||(e[16]=i(`<h1 id="安装完最小化-rhel-centos-7-后需要做的-30-件事情-四" tabindex="-1">安装完最小化 RHEL/CentOS 7 后需要做的 30 件事情（四） <a class="header-anchor" href="#安装完最小化-rhel-centos-7-后需要做的-30-件事情-四" aria-label="Permalink to “安装完最小化 RHEL/CentOS 7 后需要做的 30 件事情（四）”">​</a></h1><h3 id="_17-安装-webmin" tabindex="-1">17. 安装 Webmin <a class="header-anchor" href="#_17-安装-webmin" aria-label="Permalink to “17. 安装 Webmin”">​</a></h3><p>Webmin 是基于 Web 的 Linux 配置工具。它像一个中央系统，用于配置各种系统设置，比如用户、磁盘分配、服务以及 HTTP 服务器、Apache、MySQL 等的配置。</p><pre><code># wget http://prdownloads.sourceforge.net/webadmin/webmin-1.740-1.noarch.rpm
# rpm -ivh webmin-*.rpm
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-Webmin.jpeg" alt="在 CentOS 7 上安装 Webmin"></p><p><em>安装 Webmin</em></p>`,6)),r("p",null,[e[1]||(e[1]=t("安装完 webmin 后，你会在终端上得到一个消息，提示你用 root 密码在端口 10000 登录你的主机 (",-1)),p(n,{href:"http://ip-address:10000"},{default:o(()=>[...e[0]||(e[0]=[t("http://ip-address:10000",-1)])]),_:1}),e[2]||(e[2]=t(")。 如果运行的是无接口的服务器你可以转发端口然后从有接口的服务器上访问它。（LCTT 译注：无接口[headless]服务器指没有访问接口或界面的服务器，在此次场景，指的是是出于内网的服务器，可采用外网/路由器映射来访问该端口）",-1))]),e[17]||(e[17]=i(`<h3 id="_18-启用第三方库" tabindex="-1">18. 启用第三方库 <a class="header-anchor" href="#_18-启用第三方库" aria-label="Permalink to “18. 启用第三方库”">​</a></h3><p>添加不受信任的库并不是一个好主意，尤其是在生产环境中，这可能导致致命的问题。但仅作为例子在这里我们会添加一些社区证实可信任的库，以安装第三方工具和软件包。</p><p>为企业版 Linux（EPEL）库添加额外的软件包。</p><pre><code># yum install epel-release
</code></pre><p>添加社区企业版 Linux （Community Enterprise Linux）库：</p><pre><code># rpm -Uvh http://www.elrepo.org/elrepo-release-7.0-2.el7.elrepo.noarch.rpm
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/install-epel-repo.jpeg" alt="安装 Epel 库"></p><p><em>安装 Epel 库</em></p><p><strong>注意！</strong> 添加第三方库的时候尤其需要注意。</p><h3 id="_19-安装-7-zip-工具" tabindex="-1">19. 安装 7-zip 工具 <a class="header-anchor" href="#_19-安装-7-zip-工具" aria-label="Permalink to “19. 安装 7-zip 工具”">​</a></h3><p>在最小化安装 CentOS 时你并没有获得类似 unzip 或者 untar 的工具。我们可以选择根据需要来安装每个工具，或一个能处理所有格式的工具。7-zip 就是一个能压缩和解压所有已知类型文件的工具。</p><pre><code># yum install p7zip
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-7zip-tool.jpeg" alt="安装 7zip 工具"></p><p><em>安装 7zip 工具</em></p><p><strong>注意</strong>: 该软件包从 Fedora EPEL 7 的库中下载和安装。</p><h3 id="_20-安装-ntfs-3g-驱动" tabindex="-1">20. 安装 NTFS-3G 驱动 <a class="header-anchor" href="#_20-安装-ntfs-3g-驱动" aria-label="Permalink to “20. 安装 NTFS-3G 驱动”">​</a></h3><p>NTFS-3G，一个很小但非常有用的 NTFS 驱动，在大部分类 UNIX 发行版上都可用。它对于挂载和访问 Windows NTFS 文件系统很有用。尽管也有其它可用的替代品，比如 Tuxera，但 NTFS-3G 是使用最广泛的。</p><pre><code># yum install ntfs-3g
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-NTFS-3G.jpeg" alt="在 CentOS 上安装 NTFS-3G"></p><p><em>安装 NTFS-3G 用于挂载 Windows 分区</em></p><p>ntfs-3g 安装完成之后，你可以使用以下命令挂载 Windows NTFS 分区（我的 Windows 分区是 /dev/sda5）。</p><pre><code># mount -ro ntfs-3g /dev/sda5 /mnt
# cd /mnt
# ls -l
</code></pre><h3 id="_21-安装-vsftpd-ftp-服务器" tabindex="-1">21. 安装 Vsftpd FTP 服务器 <a class="header-anchor" href="#_21-安装-vsftpd-ftp-服务器" aria-label="Permalink to “21. 安装 Vsftpd FTP 服务器”">​</a></h3><p>VSFTPD 表示 Very Secure File Transfer Protocol Daemon，是用于类 UNIX 系统的 FTP 服务器。它是现今最高效和安全的 FTP 服务器之一。</p><pre><code># yum install vsftpd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-FTP.jpeg" alt="在 CentOS 7 上安装 Vsftpd"></p><p><em>安装 Vsftpd FTP</em></p><p>编辑配置文件 ‘/etc/vsftpd/vsftpd.conf’ 用于保护 vsftpd。</p><pre><code># vi /etc/vsftpd/vsftpd.conf
</code></pre><p>编辑一些值并使其它行保留原样，除非你知道自己在做什么。</p><pre><code>anonymous_enable=NO
local_enable=YES
write_enable=YES
chroot_local_user=YES
</code></pre><p>你也可以更改端口号，记得让 vsftpd 端口通过防火墙。</p><pre><code># firewall-cmd --add-port=21/tcp
# firewall-cmd --reload
</code></pre><p>下一步重启 vsftpd 并启用开机自动启动。</p><pre><code># systemctl restart vsftpd
# systemctl enable vsftpd
</code></pre><h3 id="_22-安装和配置-sudo" tabindex="-1">22. 安装和配置 sudo <a class="header-anchor" href="#_22-安装和配置-sudo" aria-label="Permalink to “22. 安装和配置 sudo”">​</a></h3><p>sudo 通常被称为 super do 或者 suitable user do，是一个类 UNIX 操作系统中用其它用户的安全权限执行程序的软件。让我们来看看怎样配置 sudo。</p><pre><code># visudo
</code></pre><p>这会打开 /etc/sudoers 并进行编辑</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/sudoers-File.jpeg" alt="sudoers 文件"></p><p><em>sudoers 文件</em></p><ol><li><p>给一个已经创建好的用户（比如 tecmint）赋予所有权限（等同于 root）。</p><pre><code> tecmint   ALL=(ALL)    ALL
</code></pre></li><li><p>如果给一个已经创建好的用户（比如 tecmint）赋予除了重启和关闭服务器以外的所有权限（等同于 root）。</p><p>首先，再一次打开文件并编辑如下内容：</p><pre><code> cmnd_Alias nopermit = /sbin/shutdown, /sbin/reboot
</code></pre><p>然后，用逻辑操作符（!）添加该别名。</p><pre><code> tecmint   ALL=(ALL)    ALL,!nopermit
</code></pre></li><li><p>如果准许一个组（比如 debian）运行一些 root 权限命令，比如（增加或删除用户）。</p><pre><code> cmnd_Alias permit = /usr/sbin/useradd, /usr/sbin/userdel
</code></pre><p>然后，给组 debian 增加权限。</p><pre><code> debian ALL=(ALL) permit
</code></pre></li></ol><h3 id="_23-安装并启用-selinux" tabindex="-1">23. 安装并启用 SELinux <a class="header-anchor" href="#_23-安装并启用-selinux" aria-label="Permalink to “23. 安装并启用 SELinux”">​</a></h3><p>SELinux 表示 Security-Enhanced Linux，是内核级别的安全模块。</p><pre><code># yum install selinux-policy
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-SElinux.jpeg" alt="在 CentOS 7 上安装 SElinux"></p><p><em>安装 SElinux 策略</em></p><p>查看 SELinux 当前模式。</p><pre><code># getenforce
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Check-SELinux-Mode.jpeg" alt="查看 SELinux 模式"></p><p><em>查看 SELinux 模式</em></p><p>输出是 Enforcing，意味着 SELinux 策略已经生效。</p><p>如果需要调试，可以临时设置 selinux 模式为允许。不需要重启。</p><pre><code># setenforce 0
</code></pre><p>调试完了之后再次设置 selinux 为强制模式，无需重启。</p><pre><code># setenforce 1
</code></pre><p>（LCTT 译注：在生产环境中，SELinux 固然会提升安全，但是也确实会给应用部署和运行带来不少麻烦。具体是否部署，需要根据情况而定。）</p><h3 id="_24-安装-rootkit-hunter" tabindex="-1">24. 安装 Rootkit Hunter <a class="header-anchor" href="#_24-安装-rootkit-hunter" aria-label="Permalink to “24. 安装 Rootkit Hunter”">​</a></h3><p>Rootkit Hunter，简写为 RKhunter，是在 Linux 系统中扫描 rootkits 和其它可能有害攻击的程序。</p><pre><code># yum install rkhunter
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Install-Rootkit-Hunter.jpeg" alt="安装 Rootkit Hunter"></p><p><em>安装 Rootkit Hunter</em></p><p>在 Linux 中，从脚本文件以计划作业的形式运行 rkhunter 或者手动扫描有害攻击。</p><pre><code># rkhunter --check
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/Scan-for-rootkits.png" alt="扫描 rootkits"></p><p><em>扫描 rootkits</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/04/RootKit-Results.png" alt="RootKit 扫描结果"></p><p><em>RootKit 扫描结果</em></p><hr>`,69)),r("p",null,[e[4]||(e[4]=t("via: ",-1)),p(n,{href:"http://www.tecmint.com/things-to-do-after-minimal-rhel-centos-7-installation/4/"},{default:o(()=>[...e[3]||(e[3]=[t("http://www.tecmint.com/things-to-do-after-minimal-rhel-centos-7-installation/4/",-1)])]),_:1})]),r("p",null,[e[8]||(e[8]=t("作者：",-1)),p(n,{href:"http://www.tecmint.com/author/avishek/"},{default:o(()=>[...e[5]||(e[5]=[t("Avishek Kumar",-1)])]),_:1}),e[9]||(e[9]=t(" 译者：",-1)),p(n,{href:"https://github.com/ictlyh"},{default:o(()=>[...e[6]||(e[6]=[t("ictlyh",-1)])]),_:1}),e[10]||(e[10]=t(" 校对：",-1)),p(n,{href:"https://github.com/wxy"},{default:o(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[13]||(e[13]=t("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原创翻译，",-1)),p(n,{href:"http://linux.cn/"},{default:o(()=>[...e[12]||(e[12]=[t("Linux中国",-1)])]),_:1}),e[15]||(e[15]=t(" 荣誉推出",-1))])])}const b=a(m,[["render",c]]);export{g as __pageData,b as default};
